public class binarytrees {
    private static final int MIN_DEPTH = 4;

    public static void main(String[] args) {
        final int n = Integer.parseInt(args[0]);
        final int maxDepth = n < MIN_DEPTH + 2 ? MIN_DEPTH + 2 : n;
        final int stretchDepth = maxDepth + 1;

        System.out.println("stretch tree of depth " + stretchDepth + "\t check: "
                + Tree.create(stretchDepth).check());

        final Tree longLivedTree = Tree.create(maxDepth);

        for (int depth = MIN_DEPTH; depth <= maxDepth; depth += 2) {
            final int iterations = 1 << (maxDepth - depth + MIN_DEPTH);
            final int d = depth;
            final int check = IntStream.range(0, iterations).parallel()
                    .map(i -> Tree.create(d).check())
                    .sum();
            System.out.println(iterations + "\t trees of depth " + depth + "\t check: " + check);
        }

        System.out.println("long lived tree of depth " + maxDepth + "\t check: "
                + longLivedTree.check());
    }

    private static final class Tree {
        final Tree left, right;

        Tree(Tree left, Tree right) {
            this.left = left;
            this.right = right;
        }

        static Tree create(int depth) {
            return depth > 0
                    ? new Tree(create(depth - 1), create(depth - 1))
                    : new Tree(null, null);
        }

        int check() {
            return left == null ? 1 : 1 + left.check() + right.check();
        }
    }
}
