import java.util.*;

public class Fannkuch {
    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);
        int[] p = new int[n];
        int[] q = new int[n];
        int[] s = new int[n];
        int maxflips = 0;
        int  checksum = 0;
        int  sign = 1;

        for (int i = 0; i < n; i++) {
            p[i] = i + 1;
            q[i] = i;
            s[i] = i;
        }

        do {
            int flips = 1;
            System.arraycopy(p, 0, q, 0, n);
            while (q[0] != 1) {
                int k = q[0];
                for (int i = 0; i < k; i++) {
                    s [i] = q[i];
                }
                for (int i = 0; i < k; i++) {
                    q[i] = s[k - 1 - i];
                }
                flips++;
            }
            if (flips > maxflips) maxflips = flips;
            checksum += sign * flips;
            sign = -sign;
        } while (nextPermutation(p, n));

        System.out.println(checksum);
        System.out.println("Pfannkuchen(" + n + ") = " + maxflips);
    }

    private static boolean nextPermutation(int[] p, int n ) {
        int i = n - 1;
        while (i > 0 && p[i - 1] >= p[i]) i--;
        if (i == 0) return false;
        int j = n - 1;
        while (p[j] <= p[i - 1]) j--;
        int t = p[i - 1]; p[i - 1] = p[j]; p[j] = t;
        j = n - 1;
        while (i < j) {
            t = p[i]; p[i] = p[j]; p[j] = t;
            i++; j--;
        }
        return true;
    }
}
