import java.io.OutputStream;
import java.nio.charset.StandardCharsets;

public class fasta {
    static final int LINE = 60;
    static final int IM = 139968;
    static final int IA = 3877;
    static final int IC = 29573;
    static int seed = 42;

    static final String ALU =
        "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
        "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
        "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
        "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
        "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

    static final char[] IUB_C = {
        'a', 'c', 'g', 't', 'B', 'D', 'H', 'K', 'M', 'N', 'R', 'S', 'V', 'W', 'Y'
    };
    static final double[] IUB_P = {
        0.27, 0.12, 0.12, 0.27,
        0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
        0.02, 0.02, 0.02, 0.02, 0.02
    };

    static final char[] HS_C = { 'a', 'c', 'g', 't' };
    static final double[] HS_P = {
        0.3029549426680,
        0.1979883004921,
        0.1975473066391,
        0.3015094502008
    };

    public static void main(String[] args) throws IOException {
        int n = Integer.parseInt(args[0]);
        BufferedOutputStream out = new BufferedOutputStream(System.out, 1 << 18);

        writeHeader(out, ">ONE Homo sapiens alu\n");
        repeatFasta(ALU, 2 * n, out);

        writeHeader(out, ">TWO IUB ambiguity codes\n");
        randomFasta(IUB_C, IUB_P, 3 * n, out);

        writeHeader(out, ">THREE Homo sapiens frequency\n");
        randomFasta(HS_C, HS_P, 5 * n, out);

        out.flush();
    }

    static void writeHeader(OutputStream out, String s) throws IOException {
        out.write(s.getBytes(StandardCharsets.US_ASCII));
    }

    static void repeatFasta(String alu, int n, OutputStream out) throws IOException {
        byte[] src = alu.getBytes(StandardCharsets.US_ASCII);
        int len = src.length;
        byte[] buf = new byte[len + LINE];
        for (int i = 0; i < buf.length; i++) {
            buf[i] = src[i % len];
        }
        byte nl = (byte) '\n';
        int pos = 0;
        while (n > 0) {
            int m = n < LINE ? n : LINE;
            out.write(buf, pos, m);
            out.write(nl);
            pos += m;
            if (pos >= len) {
                pos -= len;
            }
            n -= m;
        }
    }

    static void randomFasta(char[] chars, double[] probs, int n, OutputStream out)
            throws IOException {
        byte[] lut = makeLut(chars, probs);
        byte[] line = new byte[LINE + 1];
        line[LINE] = (byte) '\n';
        int full = n / LINE;
        int remain = n - full * LINE;
        int s = seed;
        for (int i = 0; i < full; i++) {
            for (int j = 0; j < LINE; j++) {
                s = (s * IA + IC) % IM;
                line[j] = lut[s];
            }
            out.write(line);
        }
        if (remain > 0) {
            for (int j = 0; j < remain; j++) {
                s = (s * IA + IC) % IM;
                line[j] = lut[s];
            }
            line[remain] = (byte) '\n';
            out.write(line, 0, remain + 1);
        }
        seed = s;
    }

    static byte[] makeLut(char[] chars, double[] probs) {
        int nch = chars.length;
        double[] cum = new double[nch];
        double cp = 0.0;
        for (int i = 0; i < nch; i++) {
            cp += probs[i];
            cum[i] = cp;
        }
        cum[nch - 1] = 1.0;
        byte[] lut = new byte[IM];
        int last = nch - 1;
        for (int i = 0; i < IM; i++) {
            double r = (double) i / IM;
            int j = 0;
            while (j < last && !(cum[j] > r)) {
                j++;
            }
            lut[i] = (byte) chars[j];
        }
        return lut;
    }
}
